const updateCommunity = `-- name: UpdateCommunity :one
UPDATE communities
SET name = COALESCE($1, name),
    slug = COALESCE($2, slug),
    description = COALESCE($3, description),
    thumbnail = COALESCE($4, thumbnail),
    banner = COALESCE($5, banner),
    visibility = COALESCE($6::community_visibility_enum, visibility),
    updated_at = now()
WHERE id = $7 AND deleted_at IS NULL
RETURNING id, name, slug, description, thumbnail, banner, visibility, owner_id, created_at, updated_at, deleted_at
`

type UpdateCommunityParams struct {
	Name        sql.NullString
	Slug        sql.NullString
	Description sql.NullString
	Thumbnail   sql.NullString
	Banner      sql.NullString
	Visibility  NullCommunityVisibilityEnum
	ID          int64
}

func (q *Queries) UpdateCommunity(ctx context.Context, arg UpdateCommunityParams) (Community, error) {
	row := q.db.QueryRowContext(ctx, updateCommunity,
		arg.Name,
		arg.Slug,
		arg.Description,
		arg.Thumbnail,
		arg.Banner,
		arg.Visibility,
		arg.ID,
	)
	var i Community
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.Thumbnail,
		&i.Banner,
		&i.Visibility,
		&i.OwnerID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
